SourceCode.Declaration:
/// <summary>
/// MPJ_22903_SalesOrderGuide
/// Responsible for expanding sales order guide into fu
/// ll list of items, for quick lookup during sales order entry/processing.
/// </summary>
final class METSalesOrderGuideExpand
{
    // Params
    public METSalesOrderGuideID orderGuideID;

    // State
    METSalesOrderGuideTable     orderGuide;
    METSalesOrderGuideLine      orderGuideLine;
    METSalesOrderGuideExpanded  expanded, expandedExists;


}

Method.Source:
    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        setPrefix(strFmt("@MET:SalesOrderGuideExpandProcessLogHeader", orderGuideID));

        orderGuide = METSalesOrderGuideTable::findThrow(orderGuideID, true);

        ttsbegin;

        // TODO monitor timing of this job.

        this.syncItemLines();
        this.syncAttributeLines();

        orderGuide.ExpandedDateTime = DateTimeUtil::getSystemDateTime();
        orderGuide.update();

        ttscommit;        

        info(strFmt("@MET:SalesOrderGuideExpandCompletionMessage",
            orderGuide.SalesOrderGuideID,
            METSalesOrderGuideExpanded::countLines(orderGuide.SalesOrderGuideID))); 
    }

/// <summary>
/// Add/remove 'item' lines as required to sync the expanded table.
/// </summary>
protected void syncItemLines()
{
    insert_recordset expanded (SalesOrderGuideID, ItemId, LineType)
    select SalesOrderGuideID, ItemId, LineType 
        from orderGuideLine
        where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
        &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Item
        &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Include
    notexists join expandedExists
        where   expandedExists.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
        &&      expandedExists.ItemId               == orderGuideLine.ItemId;
    
    delete_from expanded
        where   expanded.SalesOrderGuideID          == orderGuide.SalesOrderGuideID
        &&      expanded.LineType                   == METSalesOrderGuideLineType::Item
    notexists join orderGuideLine
        where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
        &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Item
        &&      orderGuideLine.ItemId               == expanded.ItemId;
}

    /// <summary>
    /// Add/remove 'attribute' lines as required to sync the expanded table.
    /// </summary>
    protected void syncAttributeLines()
    {
        METEcoResProductAttributeValueExpanded  productAttrValue;
        InventTable                             inventTable;

        insert_recordset expanded (SalesOrderGuideID, ItemId, LineType)
        select SalesOrderGuideID, ItemId, LineType
            from orderGuideLine
            where   orderGuideLine.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      orderGuideLine.LineType             == METSalesOrderGuideLineType::Item
            &&      orderGuideLine.IncludeExclude       == METSalesOrderGuideInclusion::Include
        join productAttrValue
            where   productAttrValue.AttributeName      == orderGuideLine.AttributeName
        join inventTable
            where   inventTable.Product                 == productAttrValue.Product
        notexists join expandedExists
            where   expandedExists.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
            &&      expandedExists.ItemId               == inventTable.ItemId;
    }

/// <summary>
/// Get/set orderGuideID
/// </summary>
/// <param name = "_orderGuideID">_orderGuideID</param>
/// <returns>orderGuideID</returns>
public METSalesOrderGuideID parmOrderGuideID(METSalesOrderGuideID _orderGuideID = orderGuideID)
{
    orderGuideID = _orderGuideID;
    return orderGuideID;
}

    public static void main(Args _args)
    {
        METSalesOrderGuideExpand    expand      = new METSalesOrderGuideExpand();
        METSalesOrderGuideTable     orderGuide  = _args.record();

        if(!orderGuide)
        {
            throw error(error::missingRecord(funcName()));
        }

        expand.parmOrderGuideID(orderGuide.SalesOrderGuideID);
        expand.run();

        if(FormDataUtil::getFormDataSource(orderGuide))
        {
            FormDataUtil::getFormDataSource(orderGuide).research();
        }        
    }
